rule.definition:
a!localVariables(
  /*triiger ID 381 - needs opposite RPPPP*/
/**/
  /*NEXT STATUS*/
  /**/
  /*127 - NBL Review*/
  /*129 - DPP Leadership Review*/
  /*131 - RPPP Review*/
  /*133 - DPP PIC Review*/
  /*135 - completed*/
  /*145 - DPP Ops Review*/
  /*147 - DPP Ops Review - Return*/
  /*148 - DPP Ops Review - Final*/
  local!isRecipientOnlyDPP: if(
    and(
      length(ri!recipients) = 1,
      contains(
        ri!recipients,
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4957932"
      ),
    ),
    true,
    false
  ),
  local!recipientsSplit: split(ri!recipients,";"),
  local!recipientsSplitCheck: if(
    and(
      ri!triggerID = #"_a-0000e777-b242-8000-9c12-011c48011c48_5295504", 
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!isEastRPPP)
    ),
    if(
      ri!isEastRPPP = true, 
      a!flatten(
        {
          local!recipientsSplit,
          "WRPPP"
        }
      ),
      a!flatten(
        {
          local!recipientsSplit,
          "ERPPP"
        }
      )
    ),
    local!recipientsSplit
  ),
  local!isRecipientIncludeDPP: if(
    and(
      length(local!recipientsSplitCheck) > 1,
      contains(
        local!recipientsSplitCheck,
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4957932"
      ),
    ),
    true,
    false
  ),
  local!recipientsSplitClean: if(
    local!isRecipientIncludeDPP = true, 
    remove(
      local!recipientsSplitCheck,
      wherecontains(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4957932",
        local!recipientsSplitCheck
      )
    ),
    local!recipientsSplitCheck
  ),
  local!recipients: #"SYSTEM_SYSRULES_forEach"(
    items: local!recipientsSplitClean,
    expression: index(
      a!groupsByName(groupName: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3085024"(fv!item)),
      1,
      null
    )
  ),
  local!users:if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipients),
    #"SYSTEM_SYSRULES_forEach"(
      items: local!recipients,
      expression: a!groupMembers(fv!item)
    ),
    null
  ),
  local!usersData: if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipients),
    a!flatten(#"SYSTEM_SYSRULES_forEach"(
      items: local!users,
      expression: property(fv!item,"data",null)
    )
    ),
    null
  ),
  local!usersClean: union(
    local!usersData,
    local!usersData
  ),
  local!emailAddressesText:#"SYSTEM_SYSRULES_forEach"(
    items: local!usersClean,
    expression: user(fv!item,"email")
  ),
  local!emailAddressesTextClean: union(
    local!emailAddressesText,
    local!emailAddressesText
  ),
  if(
    local!isRecipientOnlyDPP = true,
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4718496",
    if(
      local!isRecipientIncludeDPP = true, 
      a!flatten(
        {
          local!emailAddressesTextClean, #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4718496"
        }
      ),
      local!emailAddressesTextClean
    )
  )
)
